import { createReadStream, createWriteStream } from 'node:fs'
import { mkdir, readdir, rename, rm, stat, statfs, copyFile } from 'node:fs/promises'
import path from 'node:path'
import { Transform, type Readable } from 'node:stream'
import { pipeline } from 'node:stream/promises'
import { AppError } from '../errors'

/** Object keys are always generated by the server: `<bucket>/<random id>`. */
export type StorageBucket = 'uploads' | 'outputs'
const KEY_PATTERN = /^(uploads|outputs)\/(upl|out)_[A-Za-z0-9_-]{22}$/

export function storageKey(bucket: StorageBucket, id: string): string {
  const key = `${bucket}/${id}`
  assertKey(key)
  return key
}

function assertKey(key: string): void {
  if (!KEY_PATTERN.test(key)) throw new Error('Invalid storage key')
}

export interface StoredObject {
  key: string
  sizeBytes: number
  modifiedAt: number
}

/**
 * Private object storage. Implementations must never make objects publicly
 * readable; downloads are always served through an authorised endpoint.
 */
export interface StorageDriver {
  /** Streams data into a new object, aborting once `maxBytes` is exceeded. */
  write(key: string, source: Readable, opts: { maxBytes: number }): Promise<{ sizeBytes: number }>
  /** Moves a finished local file (e.g. conversion output) into storage. */
  importFile(key: string, localPath: string): Promise<{ sizeBytes: number }>
  /** A local filesystem path for processing tools. */
  localPath(key: string): Promise<string>
  read(key: string, range?: { start: number; end: number }): Readable
  stat(key: string): Promise<StoredObject | null>
  delete(key: string): Promise<void>
  list(): Promise<StoredObject[]>
  /** Free bytes available for new objects. */
  freeBytes(): Promise<number>
}

export class LocalStorageDriver implements StorageDriver {
  constructor(private readonly root: string) {}

  private resolve(key: string): string {
    assertKey(key)
    const full = path.resolve(this.root, key)
    // Defence in depth: keys are pattern-checked, but never allow escaping the root.
    if (!full.startsWith(path.resolve(this.root) + path.sep)) throw new Error('Storage path escapes root')
    return full
  }

  async write(key: string, source: Readable, opts: { maxBytes: number }) {
    const dest = this.resolve(key)
    const partial = `${dest}.part`
    await mkdir(path.dirname(dest), { recursive: true, mode: 0o700 })
    let size = 0
    const limiter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        size += chunk.length
        if (size > opts.maxBytes) {
          cb(new AppError('UPLOAD_TOO_LARGE', 'This file exceeds the maximum upload size.'))
          return
        }
        cb(null, chunk)
      },
    })
    try {
      await pipeline(source, limiter, createWriteStream(partial, { flags: 'wx', mode: 0o600 }))
      await rename(partial, dest)
    } catch (err) {
      await rm(partial, { force: true })
      throw err
    }
    return { sizeBytes: size }
  }

  async importFile(key: string, localPath: string) {
    const dest = this.resolve(key)
    await mkdir(path.dirname(dest), { recursive: true, mode: 0o700 })
    try {
      await rename(localPath, dest)
    } catch (err) {
      // Scratch space may live on another volume.
      if ((err as NodeJS.ErrnoException).code !== 'EXDEV') throw err
      await copyFile(localPath, dest)
      await rm(localPath, { force: true })
    }
    return { sizeBytes: (await stat(dest)).size }
  }

  async localPath(key: string) {
    return this.resolve(key)
  }

  read(key: string, range?: { start: number; end: number }) {
    return createReadStream(this.resolve(key), range ? { start: range.start, end: range.end } : undefined)
  }

  async stat(key: string) {
    const s = await stat(this.resolve(key)).catch(() => null)
    return s?.isFile() ? { key, sizeBytes: s.size, modifiedAt: s.mtimeMs } : null
  }

  async delete(key: string) {
    const full = this.resolve(key)
    await rm(full, { force: true })
    await rm(`${full}.part`, { force: true })
  }

  async list() {
    const out: StoredObject[] = []
    for (const bucket of ['uploads', 'outputs'] as const) {
      // Runtime data directory: excluded from build-time file tracing.
      const dir = path.join(/*turbopackIgnore: true*/ this.root, bucket)
      const names = await readdir(dir).catch(() => [] as string[])
      for (const name of names) {
        const s = await stat(path.join(/*turbopackIgnore: true*/ dir, name)).catch(() => null)
        if (!s?.isFile()) continue
        // Partial uploads are reported under their final key so orphan cleanup can remove them.
        const key = `${bucket}/${name.replace(/\.part$/, '')}`
        if (KEY_PATTERN.test(key)) out.push({ key, sizeBytes: s.size, modifiedAt: s.mtimeMs })
      }
    }
    return out
  }

  async freeBytes() {
    await mkdir(this.root, { recursive: true, mode: 0o700 })
    const s = await statfs(this.root)
    return s.bavail * s.bsize
  }
}
